import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.CWCEHGF4.js";const n="/MeshPaintingDoc/material-setup/01-mesh-painting-function.png",m=JSON.parse('{"title":"Material Setup","description":"","frontmatter":{},"headers":[],"relativePath":"guide/material-setup.md","filePath":"guide/material-setup.md","lastUpdated":1784811592000}'),r={name:"guide/material-setup.md"};function s(l,e,h,c,u,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="material-setup" tabindex="-1">Material Setup <a class="header-anchor" href="#material-setup" aria-label="Permalink to &quot;Material Setup&quot;">​</a></h1><p>Runtime Mesh Painting stores the painted result in UV space. Your mesh material uses the <code>Mesh Painting</code> material function to combine that runtime paint layer with the material&#39;s original look.</p><p>For a basic setup, add the <code>Mesh Painting</code> function to your material and connect its outputs to the material output:</p><ul><li><code>BaseColor</code> to <code>Base Color</code></li><li><code>Metallic</code> to <code>Metallic</code></li><li><code>Roughness</code> to <code>Roughness</code></li><li><code>Brush Emissive</code> to <code>Emissive Color</code></li></ul><p><img src="'+n+'" alt="Mesh Painting material function setup"></p><h2 id="default-setup" tabindex="-1">Default Setup <a class="header-anchor" href="#default-setup" aria-label="Permalink to &quot;Default Setup&quot;">​</a></h2><p>You do not have to plug anything into the function inputs for a first paint test. If the inputs are left empty, the function uses its default values and the mesh can still receive runtime paint.</p><p>This is the fastest way to confirm that the paint target and painting controller are working correctly.</p><p>For the brush area preview to appear on the mesh, connect <code>Brush Emissive</code> to <code>Emissive Color</code>. The paint result can still work without this connection, but the GPU preview ring will not be visible.</p><h2 id="using-your-own-material-values" tabindex="-1">Using Your Own Material Values <a class="header-anchor" href="#using-your-own-material-values" aria-label="Permalink to &quot;Using Your Own Material Values&quot;">​</a></h2><p>If your mesh already has textures or custom material values, connect them to the function inputs:</p><ul><li><code>BaseColor</code> for the original base color or base color texture.</li><li><code>Metallic</code> for the original metallic value or texture.</li><li><code>Roughness</code> for the original roughness value or texture.</li><li><code>Emissive</code> for your material&#39;s own emissive color, if it already has one.</li></ul><p>When you paint, the runtime paint layer is drawn over these values. In the painted area, the paint becomes visible instead of the original texture.</p><h2 id="brush-preview-emissive" tabindex="-1">Brush Preview Emissive <a class="header-anchor" href="#brush-preview-emissive" aria-label="Permalink to &quot;Brush Preview Emissive&quot;">​</a></h2><p><code>Brush Emissive</code> is the output used by the GPU brush area preview. It shows the ring that marks where the brush will paint.</p><p>Use <code>BrushEmissivePower</code> when you want to control the brightness of the preview inside the material. The controller also has <code>Brush Area Preview Emissive Intensity</code>, so the usual setup is:</p><ul><li>Keep <code>BrushEmissivePower</code> at its default unless the material needs a different preview strength.</li><li>Adjust <code>Brush Area Preview Emissive Intensity</code> on <code>PaintingModeControllerComponent</code> for gameplay/UI tuning.</li><li>Keep <code>Brush Area Preview Color</code> white if the preview should follow the current paint color.</li></ul><p>This emissive preview is visual feedback only. It is not the stored paint color.</p><h2 id="material-settings-painting" tabindex="-1">Material Settings Painting <a class="header-anchor" href="#material-settings-painting" aria-label="Permalink to &quot;Material Settings Painting&quot;">​</a></h2><p>The plugin can paint base color and, when enabled on the target component, material settings.</p><p><code>Create Painted Material Settings Render Target</code> on <code>RuntimeMeshPaintTargetComponent</code> creates the additional render target used for painted metallic and roughness data. Keep it enabled if you want the <code>Metallic</code> and <code>Roughness</code> outputs from the material function to change when painting.</p><p><code>Initial Material Settings Color</code> uses the red and green channels as the starting material settings:</p><ul><li><code>R</code> = initial metallic</li><li><code>G</code> = initial roughness</li></ul><p>The plugin manages the remaining mask channels internally.</p><h2 id="alpha" tabindex="-1">Alpha <a class="header-anchor" href="#alpha" aria-label="Permalink to &quot;Alpha&quot;">​</a></h2><p><code>Alpha</code> controls how strongly the runtime paint covers the original material.</p><p>By default, <code>Alpha</code> is <code>1</code>, so painted areas fully show the paint result. If you lower or customize this value, the original material can remain visible together with the painted color.</p><h2 id="uv-index" tabindex="-1">UV Index <a class="header-anchor" href="#uv-index" aria-label="Permalink to &quot;UV Index&quot;">​</a></h2><p><code>UV Index</code> is important. It tells the material function which UV channel should be used for the runtime paint lookup.</p><p>This value must match the <code>UVChannel</code> value on <code>RuntimeMeshPaintTargetComponent</code>.</p><p>If the material uses a different UV index than the paint target component, the paint can appear in the wrong place, stretch incorrectly, or show up on unrelated parts of the mesh.</p><h2 id="quick-check" tabindex="-1">Quick Check <a class="header-anchor" href="#quick-check" aria-label="Permalink to &quot;Quick Check&quot;">​</a></h2><p>Before testing in a full character or production material, verify the setup on a simple mesh:</p><ul><li>Add <code>RuntimeMeshPaintTargetComponent</code> to the mesh actor.</li><li>Add the <code>Mesh Painting</code> material function to the mesh material.</li><li>Connect <code>Brush Emissive</code> to <code>Emissive Color</code> if you want the brush area preview.</li><li>Make sure <code>UV Index</code> matches the target component&#39;s <code>UVChannel</code>.</li><li>Enter paint mode and confirm that the brush paints the expected surface.</li></ul>',34)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
